INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_2_002_001", 1000, 3000, 2, "vo_minigame_1013_icon_1_002_001", "訓練はまだ\nここからですわ", 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_2_003_001", 5000, 3000, 2, "vo_minigame_1013_icon_1_003_001", "クスクス、悪くない\n流れですわね", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_2_004_001", 10000, 3000, 3, "vo_minigame_1013_icon_1_004_001", "すばらしい\n記録ですわ", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 3, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_2_005_001", 10000, 3000, 3, "vo_minigame_1013_icon_1_005_001", "乗りに乗って\nいますわね", 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 3, "見てろよ！\nマコト班の快進撃だ！", "vo_minigame_1013_icon_2_005_002", 10000, 3000, 3, "vo_minigame_1013_icon_1_005_002", "まだまだ行きます\nついてきなさい", 5);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 3, "うおぉぉっ！\n絶好調だぜ！", "vo_minigame_1013_icon_2_005_003", 10000, 3000, 3, "vo_minigame_1013_icon_1_005_003", "エリコ班の\n本領発揮ですわ！", 6);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 4, "どこまで行けるか\n楽しみだなっ！", "vo_minigame_1013_icon_2_006_001", 0, 3000, 3, "vo_minigame_1013_icon_1_006_001", "ここからは\n前人未到の領域です！", 7);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 5, "まだ諦めんなよっ", "vo_minigame_1013_icon_2_007_001", 1, 1000, 4, "vo_minigame_1013_icon_1_007_001", "厄介でしたわ…", 8);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 5, "冷やっとしたぜ…！", "vo_minigame_1013_icon_2_007_002", 1, 1000, 4, "vo_minigame_1013_icon_1_007_002", "油断大敵です", 9);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 5, "弱音を吐くなっ", "vo_minigame_1013_icon_2_007_003", 1, 1000, 4, "vo_minigame_1013_icon_1_007_003", "忌々しいっ…", 10);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, 6, "マコト班集合！", "vo_minigame_1013_icon_2_008_001", 99, 1500, 3, "vo_minigame_1013_icon_1_008_001", "大所帯ですわね", 11);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, 6, "連携してくぞ！", "vo_minigame_1013_icon_2_008_002", 99, 1500, 3, "vo_minigame_1013_icon_1_008_002", "エリコ班へようこそ", 12);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, 8, "みんなに力を！", "vo_minigame_1013_icon_2_020_001", 0, 3000, 6, "vo_minigame_1013_icon_1_020_001", "ナナカちゃんに\nお任せあれ", 13);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, 9, "任せてくれたまえ", "vo_minigame_1013_icon_2_022_001", 0, 3000, 7, "vo_minigame_1013_icon_1_022_001", "はっはっは！\n任せろ！", 14);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, 10, "ほな、いきまひょか", "vo_minigame_1013_icon_2_023_001", 0, 3000, 8, "vo_minigame_1013_icon_1_023_001", "どんどんいくわよ", 15);
